<?php
function cxQuoteDate($date) {return (new DateTimeImmutable($date))->format('d/m/Y');}
function cxWuanukoQuoteHtml(array $doc) {
    $s=$doc['Instantanea'];$e=$s['empresa'];$client=$s['cliente'];$work=$s['obra'];$profile=$s['perfilComercial'];$c=$doc['Condiciones'];$pay=$doc['Pago'];
    $code='CW-'.$doc['Anio'].'-'.str_pad($doc['Numero'],5,'0',STR_PAD_LEFT);$tariff=$doc['Tipo']==='TARIFARIO';$rate=$doc['TasaImpuesto'];$included=(int)$doc['PreciosIncluyenImpuesto'];$logo=cxDocumentLogo($e);
    $h='<!doctype html><html lang="es"><head><meta charset="utf-8"><title>'.cxEscape($code).'</title><style>
    @page{margin:20px 24px 16px}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;font-size:11.5px;font-weight:700;color:#182f43;line-height:1.2;margin:0}table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{vertical-align:top}p{margin:2px 0}h1{font-size:18px;line-height:1.25;margin:3px 0;color:#164a80}h2{font-size:11.5px;letter-spacing:.8px;color:#164a80;margin:5px 0 4px}small,.muted{font-size:10.5px;font-weight:700;color:#304d65}.head{border-bottom:3px solid #2466a0;padding-bottom:6px}.head td{padding:0 6px 4px}.eyebrow{font-size:9.5px;letter-spacing:1px;color:#43779e}.logo{width:94px;height:62px;object-fit:contain}.code{font-size:16px;font-weight:bold;color:#164a80}.ribbon{background:#eef5fb;padding:4px;margin:5px 0}.ribbon td{padding:4px 8px}.right{text-align:right}.meta td{padding:5px 7px;background:#f4f8fb;border:1px solid #d8e4ee;width:50%}.label{font-size:9.5px;text-transform:uppercase;letter-spacing:.7px;color:#56758f}.intro{margin:5px 0}.items th{background:#174e7d;color:white;padding:5px 5px;font-size:10.5px;text-align:left}.items td{padding:5px 5px;border-bottom:1px solid #d8e4ee}.items tr{page-break-inside:avoid}.num{text-align:right!important;white-space:nowrap}.itemdesc{white-space:pre-line;overflow-wrap:break-word}.totals td{padding:4px 7px}.grand td{background:#174e7d;color:#fff;font-weight:bold;font-size:15px;padding:7px}.conditions{padding-left:16px;margin:5px 0}.conditions li{margin:1px 0}.bank td{width:50%;padding:5px 8px;background:#eef5fb;border:1px solid #d8e4ee;font-size:10.5px}.contact td{padding:3px 0}.keep{page-break-inside:avoid}.footer{font-size:9.5px;border-top:2px solid #2466a0;padding-top:6px;margin-top:8px;color:#526a7f}.demo{color:#a24a15;font-weight:bold;margin-bottom:6px}.notice{font-size:9.5px;color:#62778a;margin-top:8px}.note{white-space:pre-wrap;overflow-wrap:break-word}
    @media screen{body{font-size:14px;max-width:950px;margin:24px auto;padding:26px;background:white}html{background:#eaf0f5}small,.muted,.items th,.bank td{font-size:12px}.label,.eyebrow,.footer,.notice{font-size:11px}h2{font-size:14px}}@media print{body{max-width:none;margin:0;padding:0}}
    </style></head><body>';
    if(!empty($doc['EsPrueba']))$h.='<div class="demo">DATOS DE PRUEBA - NO UTILIZAR PARA OPERACIÓN</div>';
    $h.='<table class="head"><tr><td style="width:20%">'.($logo?'<img class="logo" src="'.$logo.'" alt="Wuanuko Mix">':'').'</td><td style="width:80%"><div class="eyebrow">CONCRETO PREMEZCLADO · SUMINISTRO PARA TU OBRA</div><h1>'.cxEscape($e['RAZONSOCIAL']).'</h1><p><strong>RUC '.cxEscape($e['RUC']).'</strong></p><p class="muted">'.cxEscape($profile['servicios']).'</p><p class="muted">Domicilio fiscal: '.cxEscape($e['DIRECCION']??'').'</p></td></tr></table>';
    $h.='<table class="ribbon"><tr><td style="width:55%"><div class="label">'.($tariff?'TARIFARIO DE CONCRETO':'COTIZACIÓN / PROFORMA').'</div><div class="code">'.cxEscape($code).' <small>Versión '.$doc['Version'].'</small></div></td><td class="right" style="width:45%">Emisión: '.cxQuoteDate($doc['FechaEmision']).'<br>Válida hasta: <strong>'.cxQuoteDate($doc['VigenteHasta']).'</strong><br>Moneda: '.cxEscape($doc['Moneda']).'</td></tr></table>';
    $h.='<table class="meta"><tr><td><div class="label">PREPARADA PARA</div><strong>'.cxEscape($client['Cliente']).'</strong><p>'.(strlen($client['DniRuc'])===11?'RUC':'DNI').': '.cxEscape($client['DniRuc']).'</p><p>'.cxEscape($client['Direccion']??'').'</p></td><td><div class="label">OBRA / LUGAR DE SUMINISTRO</div><strong>'.cxEscape($work['Nombre']?:'Por definir al confirmar el pedido').'</strong><p>'.cxEscape($work['Direccion']??'').'</p><p>'.cxEscape(implode(' / ',array_filter([$work['Distrito']??'',$work['Provincia']??'',$work['Departamento']??'']))).'</p>'.(!empty($work['Contacto'])?'<p>Contacto: '.cxEscape($work['Contacto']).' '.cxEscape($work['Telefono']??'').'</p>':'').'</td></tr></table>';
    $h.='<p class="intro">De nuestra consideración: presentamos nuestra propuesta de concreto premezclado y servicios para su proyecto, de acuerdo con las características y condiciones indicadas a continuación.</p><table class="items"><thead><tr><th style="width:5%">N°</th><th style="width:44%">Descripción / características</th><th class="num" style="width:10%">Cant.</th><th style="width:7%">Und.</th><th class="num" style="width:16%">P. unitario<br>sin IGV</th><th class="num" style="width:18%">'.($tariff?'P. con IGV':'Importe<br>con IGV').'</th></tr></thead><tbody>';
    foreach($doc['partidas'] as $i=>$item){
        $spec=$item['Instantanea']['especificacion']??null;$net=$included?bcdiv($item['PrecioUnitario'],bcadd('1',bcdiv($rate,'100',12),12),12):$item['PrecioUnitario'];$details=[];
        if($spec){$details[]="f'c ".cxDisplayDecimal($spec['Resistencia']).' '.$spec['UnidadResistencia'];if(!empty($spec['EdadDias']))$details[]=$spec['EdadDias'].' días';if(!empty($spec['SlumpMin']))$details[]='Slump: '.cxDisplayDecimal($spec['SlumpMin']).' - '.cxDisplayDecimal($spec['SlumpMax']??$spec['SlumpMin']);}
        $discount=$item['Instantanea']['descuentoImporte']??null;if($discount!==null&&bccomp($discount,'0',2)>0)$details[]='Descuento con IGV: '.cxDisplayDecimal($discount);elseif(bccomp($item['DescuentoPct'],'0',4)>0)$details[]='Descuento: '.cxDisplayDecimal($item['DescuentoPct']).'%';
        if(!empty($item['Incluido']))$details[]='Incluido sin cargo adicional';if(bccomp($item['Minimo'],'0',4)>0)$details[]='Mínimo de cobro: '.cxDisplayDecimal($item['Minimo'],4).' '.$item['Unidad'];
        $q=$tariff?'1':(bccomp($item['Cantidad'],$item['Minimo'],4)<0?$item['Minimo']:$item['Cantidad']);$amount=cxAmounts($q,$item['PrecioUnitario'],$item['DescuentoPct'],(int)$item['Incluido'],$rate,$included,$discount);
        $h.='<tr><td>'.($i+1).'</td><td><strong class="itemdesc">'.nl2br(cxEscape($item['Descripcion'])).'</strong>'.($details?'<p class="muted">'.cxEscape(implode(' · ',$details)).'</p>':'').'</td><td class="num">'.($tariff?'-':cxDisplayDecimal($item['Cantidad'],2)).'</td><td>'.cxEscape($item['Unidad']==='m3'?'m³':$item['Unidad']).'</td><td class="num">'.cxDisplayDecimal(cxRound($net)).'</td><td class="num">'.cxDisplayDecimal($amount['total']).'</td></tr>';
    }
    $h.='</tbody></table>';
    if($tariff)$h.='<p class="notice">Tarifas alternativas por unidad; no representan una compra acumulada. Se elegirán cantidades al confirmar el pedido.</p>';
    else $h.='<table class="totals keep" style="margin-top:8px"><tr><td style="width:60%" rowspan="3"><span class="muted">Los precios unitarios se muestran sin IGV.<br>Los importes incluyen IGV y los descuentos indicados.<br>El detalle se calcula con la precisión original del precio.</span></td><td style="width:20%">Base imponible</td><td style="width:20%" class="num">'.cxDisplayDecimal($doc['Base']).'</td></tr><tr><td>IGV '.cxDisplayDecimal($rate,2).'%</td><td class="num">'.cxDisplayDecimal($doc['Impuesto']).'</td></tr><tr class="grand"><td>TOTAL '.cxEscape($doc['Moneda']).'</td><td class="num">'.cxDisplayDecimal($doc['Total']).'</td></tr></table>';
    $h.='<h2>CONDICIONES COMERCIALES Y DE SUMINISTRO</h2><ul class="conditions"><li><strong>Pago: '.($pay['modalidad']==='CREDITO'?'crédito':'contado').'.</strong> '.(!empty($pay['vencimiento'])?'Vencimiento: '.cxQuoteDate($pay['vencimiento']).'. ':'').'Vigencia: '.(new DateTimeImmutable($doc['FechaEmision']))->diff(new DateTimeImmutable($doc['VigenteHasta']))->days.' días desde la emisión; vencido este plazo se requiere una nueva cotización.</li><li>Traslado: '.(!empty($c['trasladoIncluido'])?'incluido en el precio del concreto':'según servicio contratado').'. Bombeo: '.(!empty($c['bombeoIncluido'])?'incluido':'según las partidas cotizadas').'.</li><li>Solicitar atención con '.(bccomp($c['anticipacionHoras'],'0',4)>0?cxDisplayDecimal($c['anticipacionHoras'],0):'por confirmar:').' horas de anticipación. Permanencia máxima del concreto en obra: '.(bccomp($c['permanenciaMinutos'],'0',4)>0?cxDisplayDecimal($c['permanenciaMinutos'],0):'por confirmar:').' minutos.</li><li>Edades de ensayo: '.cxEscape($c['ensayosDias']?implode(', ',$c['ensayosDias']).' días':'por confirmar').'.</li>';
    foreach($profile['condicionesTecnicas'] as $term)$h.='<li>'.cxEscape($term).'</li>';
    $h.='</ul>';
    foreach(['requisitosAcceso'=>'Acceso a obra','particulares'=>'Observaciones de esta cotización'] as $key=>$label)if(!empty($c[$key]))$h.='<p class="note"><strong>'.$label.':</strong> '.cxEscape($c[$key]).'</p>';
    if(bccomp($pay['adelantoPactadoPct'],'0',4)>0)$h.='<p>Adelanto pactado: '.cxDisplayDecimal($pay['adelantoPactadoPct']).'%. Este documento no acredita su recepción.</p>';
    if(!empty($pay['cuentaReferencia']))$h.='<p class="note">Referencia de cobro pactada: '.cxEscape($pay['cuentaReferencia']).'</p>';
    $h.='<div class="keep"><h2>INFORMACIÓN PARA EL PAGO</h2><table class="bank"><tr>';
    foreach($profile['cuentas'] as $bank)$h.='<td><strong>'.cxEscape($bank['banco']).'</strong><p>Cuenta: '.cxEscape($bank['cuenta']).'</p><p>CCI: '.cxEscape($bank['cci']).'</p></td>';
    $h.='</tr></table><h2>COORDINACIÓN COMERCIAL</h2><table class="contact"><tr>';
    foreach($profile['contactos'] as $contact)$h.='<td><strong>'.cxEscape($contact['nombre']).'</strong><br>'.cxEscape($contact['telefonos']).'</td>';
    $h.='</tr></table><p>'.cxEscape($profile['cierre']).'</p><div class="footer">'.cxEscape($profile['direccionComercial']).'<br>'.cxEscape($profile['correoComercial']).'<br>'.cxEscape($code).' · Versión '.$doc['Version'].' · Referencia ERP '.$doc['IdProforma'].'</div><p class="notice">Propuesta comercial sujeta a aceptación. No constituye factura, constancia de pago, receta aprobada ni autorización de despacho. La empresa emisora se conservará al confirmar el pedido.</p></div></body></html>';
    return $h;
}
